INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504420-fin315', 'stk-user9840', 'FIN 315', 'info', '{"desc": "هذا الموضوع مخصص لمناقشة المقرر المذكور في العنوان\nبنود تساعد في تقييم المقرر:\n\nجودة المقرر بشكل عام\nالمواضيع التي يغطيها المقرر\nالكتاب المستخدم للمقرر\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\n\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\n\nكما نرجو تحري الصدق والعدل في تقييم المقرر\nوعدم الخلط بين تقييم الأستاذ وتقييم المقرر بذاته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fin-315-corporate-finance/180796/1", "user": "user9840", "ts": 1546440734000, "tid": 180796, "pn": 1}}', 1546440734000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-fin315', 'stk-kbsc', 'FIN 315', 'doc', '{"docs": [{"id": "stk-dr-f175795", "n": "Dr. Naji Al-Shammasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nناجي الشماسي\n\nالمادة: *\n\nFin 315\n\nطريقة الشرح : *\n\nحيوية و جماعية\n\nالكويزات :\n\nسهلة الى متوسطة\n\nالمياجر/ميد:\n\nميدتيرم متوسط الصعوبة\n\nالفاينل :\n\nطريقة التحضير :\n\nبداية كل محاضرة\n\nالقريد النهائي الخاص بك :\n\nA+\nاضافات:\n\nقلب الفاينناس النابض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507357-fin315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naji-al-shammasi/175795/3", "user": "KBSC", "ts": 1552816556000, "tid": 175795, "pn": 3}}]}', 1552816556000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-fin315', 'stk-guest', 'FIN 315', 'doc', '{"docs": [{"id": "stk-dr-f182901", "n": "Dr. Mansour Al-Sahlawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Fin 315- term 192\nترم الكورونا\n\nبنود التقييم :\n\nالتحضير :\nيحضر أول الكلاس ودقيق في التحضير، إذا عدى اسمك بتاخذ ليت\n\nطريقة الشرح :\nجدا واضحة وجميلة طبعا يبدأ الدكتور في بعض الأحيان بنقاش عن الاخبار الاقتصادية بداية الكلاس، ثم يشرح الموضوع بالسلايدات ويضيف عليها من كلام الكتاب ويحاول يربطه بواقع الحياة وإذا ما فهمت شيء يعيده لك، وبعد ما يخلص الكلام النظري يحل كم مسألة، وفي بعض الأحيان يعطي واجب.\nحذاري تمسك الجوال أثناء الشرح\n\nالكويزات : سهلة إلى متوسطة ، أعطاني كويزين اختيارات، ثم لما جات الكورونا اعطانا بالاولويات كويز اوبن بوك وكويزين اختيارات.\n\nالبروجكت : دراسة جدوى لمشروع - أنت تختاره - لإحدى شركات تاسي ، مع تحليل عام للشركة ، وتحدد هل المشروع جيد أو لا طبعا بالأدلة\nالمشروع يتجزأ إلى بوربوينت\nو ريبورت واكسل فيه تفاصيل العمليات والافتراضات الي بنيت عليها\n( ما ذكرت التفاصيل ، ملحوق عليها اذا اخذت المادة )\n\nالمياجر: اختبرنا فقط الميجر الاول، باختصار للميجر يختبر فهمك مو حفظك ولا يخرج أبدا عن الي شرحه ومتنوع\n\n( تصحيحه ممتاز )\n\nالفاينلات : فاينل اونلاين - كورونا - ٥ أسئلة كانت مقالية عن النظريات ووو تكتب من فهمك ،ما كان فيها حساب ، طبعا لأنه اونلاين، لكن ما أعلم كيف بيكون في الوضع الطبيعي\nالقريد النهائي: b\nالصوت: الصوت واضح\n\nإضافات :\n\nالدكتور مزاجي جدا فحاول تتعامل بحذر وإذا كنت من المشاركين والي يسألونه يعطيك عيونه ( لكن كن حذر باختيار كلماتك )أما إذا كنت مزلب فالله يعينك\n\nيحاول يساعد طلابه في الدرجات في آخر الترم قدر المستطاع (خصوصًا اذا كان افرچ سكاشنه مرتفع ، حسب كلام طلابه ب فاينانس ٢٥٠) ، بالمختصر يعطيك حقك وزيادة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524612-fin315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mansour-al-sahlawi/182901/4", "user": "Guest", "ts": 1597183941000, "tid": 182901, "pn": 4}}]}', 1597183941000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
